"""Model-facing tools, resource, prompt, and correctable validation errors."""

import json
import logging
from collections.abc import Awaitable, Callable
from dataclasses import dataclass, field
from typing import Annotated

from mcp import McpError, types
from mcp.server import Server
from mcp.server.lowlevel.helper_types import ReadResourceContents
from pydantic import AwareDatetime, BaseModel, ConfigDict, Field, ValidationError, field_validator, model_validator

from reel_library.catalog import AssetType, Catalog, CatalogError, Search, check_relative_path

LOGGER = logging.getLogger(__name__)
STATS_URI = "reel://catalog/statistics"
PROMPT_NAME = "plan_project_organization"
AssetId = Annotated[str, Field(pattern=r"^asset-[0-9]{3}$", description="Asset ID from search_assets, such as asset-001.")]
Project = Annotated[str, Field(pattern=r"^[a-zA-Z0-9][a-zA-Z0-9-]{0,47}$", description="Project slug, such as neon-harbor.")]
Tag = Annotated[str, Field(pattern=r"^[a-zA-Z0-9][a-zA-Z0-9-]{0,31}$", description="One tag such as night or approved. Matching is case-insensitive.")]


class ToolArgs(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)


class SearchArgs(ToolArgs):
    tag: Tag | None = None
    type: AssetType | None = Field(None, description="Media type: image, video, or audio.")
    project: Project | None = None
    path_prefix: str | None = Field(None, max_length=255, description="Library-relative folder such as neon-harbor/image. Use slash-separated folders without a leading or trailing slash or dot segments.")
    created_from: AwareDatetime | None = Field(None, description="Inclusive lower bound as an RFC 3339 date-time with a time zone.")
    created_before: AwareDatetime | None = Field(None, description="Exclusive upper bound as an RFC 3339 date-time with a time zone.")
    limit: int = Field(10, ge=1, le=20, description="Maximum results in one page (1–20).")
    offset: int = Field(0, ge=0, le=10000, description="Start at 0. To continue, use next_offset returned by the previous page.")

    @field_validator("path_prefix")
    @classmethod
    def validate_path(cls, path: str | None) -> str | None:
        return check_relative_path(path) if path is not None else None

    @model_validator(mode="after")
    def validate_dates(self):
        if self.created_from is not None and self.created_before is not None and self.created_from >= self.created_before:
            raise ValueError("created_before must be later than created_from.")
        return self


class AssetArgs(ToolArgs):
    asset_id: AssetId


class TagArgs(AssetArgs):
    add: list[Tag] = Field(default_factory=list, max_length=12, description="Tags to add. Existing tags stay in place.")
    remove: list[Tag] = Field(default_factory=list, max_length=12, description="Tags to remove. Absent tags are ignored.")

    @model_validator(mode="after")
    def validate_changes(self):
        self.add = sorted({tag.lower() for tag in self.add})
        self.remove = sorted({tag.lower() for tag in self.remove})
        if not self.add and not self.remove:
            raise ValueError("Provide at least one tag in add or remove.")
        if set(self.add).intersection(self.remove):
            raise ValueError("Use disjoint add and remove lists for one call.")
        return self


class ProjectArgs(ToolArgs):
    project: Project


